# POST /api/sheets/{sheetId}/today — change the sheet's today (the date everything on it goes by).
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetToday
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplySheetToday
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# POST /api/sheets/{sheetId}/settings — change a setting; an unknown key or a bad value is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: set
set:
  class: net.officefloor.hq.app.setting.ChangeSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.RecordSettingChanged
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSetting
# POST /api/sheets/{sheetId}/periods/{name}/close — close a period, fixing its due-total; refused
# (409) when it is already closed, and (403) for a role the permission matrix does not let close.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ApplySheetToday {
    public void apply(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val LocalDate today, SheetRepository repository, Out<Sheet> sheet) {
        String id = sheetId.trim();
        repository.open(id, by == null ? "" : by);
        repository.setToday(id, today);
        sheet.set(repository.find(id));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetToday {
    public void validate(@RequestBody SheetTodayRequest request, Out<LocalDate> today)
            throws InvalidSheetTodayException {
        String value = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetTodayException("Not a date: " + value);
        }
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0 or more, with up to two decimals. */
    private static final Pattern MONEY = Pattern.compile("(\\d+(\\.\\d{0,2})?|\\.\\d{1,2})");

    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,6}");

    /** The grades that may have their own terms. */
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The roles a permission may name. */
    private static final Set<String> ROLES = Set.of(Role.CLERK, Role.STEWARD);

    public void validate(@RequestBody SettingRequest request, Out<SettingRequest> body)
            throws InvalidSettingException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String value = request == null || request.value() == null ? "" : request.value().trim();
        String from = request == null || request.from() == null || !SettingRepository.isDated(key)
                ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("A setting's from-date is blank or a date (yyyy-MM-dd)");
            }
        }
        String given = from.isEmpty() ? null : from;
        if (SettingRepository.CLERK_LIMIT.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The clerk limit is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.PROOF_THRESHOLD.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The proof threshold is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.CAP.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The cap is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.FLOOR.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The floor is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.LATE_PCT.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The late percent is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.TERMS.equals(key)) {
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The terms are a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, String.valueOf(Integer.parseInt(value)), given));
            return;
        } else if (key.startsWith(SettingRepository.TERMS_OF_GRADE)
                && GRADES.contains(key.substring(SettingRepository.TERMS_OF_GRADE.length()))) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("A grade's terms are blank or a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), given));
            return;
        } else if (SettingRepository.POLICY_DATE.equals(key)
                || SettingRepository.PERIOD_NUMBERING_FROM.equals(key)) {
            if (!value.isEmpty()) {
                try {
                    value = LocalDate.parse(value).toString();
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The " + key + " setting is blank or a date (yyyy-MM-dd)");
                }
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : value, null));
            return;
        } else if (Permissions.isKey(key)) {
            List<String> roles = Permissions.roles(value);
            if (!roles.stream().allMatch(ROLES::contains)) {
                throw new InvalidSettingException("A permission is blank or a comma separated list of clerk and steward");
            }
            body.set(new SettingRequest(key, roles.isEmpty() ? null : String.join(",", roles), null));
            return;
        } else {
            throw new InvalidSettingException("Unknown setting: " + key);
        }
        body.set(new SettingRequest(key,
                value.isEmpty() ? null : new BigDecimal(value).setScale(2).toPlainString(), given));
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ChangeSetting {
    public void set(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val SettingRequest request, SheetRepository sheets, SettingRepository settings,
            Out<Setting> setting) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        sheets.open(id, user);
        // A dated key's value applies from its from-date, by default the sheet's today.
        LocalDate from = !SettingRepository.isDated(request.key()) ? null
                : request.from() != null ? LocalDate.parse(request.from()) : sheets.today(id);
        setting.set(settings.set(id, request.key(), request.value(), from, user));
    }
}
package net.officefloor.hq.app.setting;

/** A sheet setting: its key and its value as text ("" when blank), in force from its from-date
 *  (yyyy-MM-dd; null: from the beginning of time, and always for an undated key). */
public record Setting(String sheetId, String key, String value, String from) {
}
package net.officefloor.hq.app.setting;

import java.util.List;

/** A dated setting's values by from-date, and the value it has before every from-date ({@code start};
 *  null: none). */
public record DatedSetting(List<Setting> values, String start) {

    /** The value in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
     *  it (none: from the beginning of time), else the starting value; null when blank or none. */
    public String on(String date) {
        Setting found = null;
        for (Setting s : values) {
            if (s.from() != null && s.from().compareTo(date) > 0) continue;
            if (found == null || nz(found.from()).compareTo(nz(s.from())) < 0) found = s;
        }
        if (found == null) return start;
        return found.value().isEmpty() ? null : found.value();
    }

    private static String nz(String from) {
        return from == null ? "" : from;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Closes a period, fixing its due-total as it is now: the due, as the screen shows it now, of the claims
 *  whose date falls in it that counted by their status at the end of its last day as their status log
 *  records it (n/a ones skipped, and those the live rules leave out: deferred, or OPEN ones dated within
 *  a hold of their person, unless bound).
 *  Each person's due-total for it is fixed too, for everyone on the sheet. Refused when it is already closed, and for a role
 *  the permission matrix does not let close. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository log, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException, PeriodPermissionException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.CLOSE, roles, settings)) {
            throw new PeriodPermissionException("Your role may not close a period");
        }
        if (found.closed()) {
            throw new PeriodClosedException("The period is already closed");
        }
        DatedSetting floor = settings.floor(id);
        Dues.Late late = settings.late(id, sheets.today(id));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person p : people.list(id)) personTotals.put(p.getId(), BigDecimal.ZERO.setScale(2));
        Map<Long, String> atEnd = log.statusesOn(id, LocalDate.parse(found.to()));
        for (Claim c : claims.list(id)) {
            if (!found.contains(c.getDate())) continue;
            String status = atEnd.containsKey(c.getId()) ? atEnd.get(c.getId()) : c.getStatus();
            if (status == null || !(ClaimStatus.isOpen(status) || ClaimStatus.SETTLED.name().equals(status))) continue;
            Person person = people.find(id, c.getPersonId());
            if (person != null && person.leftOutLive(c)) continue;
            Rate rate = person == null ? null
                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()));
            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor.on(c.getDate()), late.rounding(c.getRoundDate())), late);
            if (due != null) {
                total = total.add(new BigDecimal(due));
                if (person != null) personTotals.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
            }
        }
        period.set(periods.close(found, total, personTotals, by == null ? "" : by));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
